import sqlite3
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE customers(id INT, name TEXT);
CREATE TABLE orders(id INT, customer_id INT, status TEXT);
INSERT INTO customers VALUES (1,'Asha'),(2,'Ben'),(3,'Cy');
INSERT INTO orders VALUES (10,1,'paid'),(11,1,'open'),(12,2,'open');
""")
q = {
 "filter in ON   ": "SELECT c.name, o.id FROM customers c LEFT JOIN orders o ON o.customer_id=c.id AND o.status='paid'",
 "filter in WHERE": "SELECT c.name, o.id FROM customers c LEFT JOIN orders o ON o.customer_id=c.id WHERE o.status='paid'",
 "anti-join      ": "SELECT c.name FROM customers c LEFT JOIN orders o ON o.customer_id=c.id WHERE o.id IS NULL",
}
for k, sql in q.items():
    print(k, db.execute(sql).fetchall())
# ON keeps Ben and Cy (NULL-padded); WHERE drops them -> acts like INNER JOIN

import sqlite3
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE customers(id INT, name TEXT);
CREATE TABLE orders(id INT, customer_id INT);
INSERT INTO customers VALUES (1,'Asha'),(2,'Asha'),(3,'Ben');
INSERT INTO orders VALUES (10,1),(11,1),(12,1),(13,2),(14,3);
""")
def run(t, sql): print(t, db.execute(sql).fetchall())
# Semi-join: each customer once, stops at first matching order
run("EXISTS          ", "SELECT id, name FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id=c.id)")
# JOIN multiplies rows: customer 1 appears 3 times
run("JOIN (raw)      ", "SELECT c.id, c.name FROM customers c JOIN orders o ON o.customer_id=c.id")
# DISTINCT on the name merges the two different customers called Asha
run("JOIN + DISTINCT ", "SELECT DISTINCT c.name FROM customers c JOIN orders o ON o.customer_id=c.id")

import sqlite3
db = sqlite3.connect(":memory:")
db.executescript("""
CREATE TABLE stores(name TEXT); CREATE TABLE days(d TEXT);
CREATE TABLE sales(store TEXT, d TEXT, amount INT);
INSERT INTO stores VALUES ('North'),('South');
INSERT INTO days VALUES ('Mon'),('Tue'),('Wed');
INSERT INTO sales VALUES ('North','Mon',10),('North','Wed',7),('South','Tue',5);
""")
print("plain join (missing days vanish):")
for r in db.execute("SELECT store,d,amount FROM sales ORDER BY store,d"): print(" ", r)
# CROSS JOIN builds every (store, day) pair, LEFT JOIN adds the facts, COALESCE fills 0
sql = """SELECT st.name, dy.d, COALESCE(s.amount,0)
  FROM stores st CROSS JOIN days dy
  LEFT JOIN sales s ON s.store=st.name AND s.d=dy.d ORDER BY st.name, dy.d"""
print("scaffold (zero-filled):")
for r in db.execute(sql): print(" ", r)
print("pair count:", db.execute("SELECT COUNT(*) FROM stores CROSS JOIN days").fetchone()[0], "= 2 x 3")
